DO $$ DECLARE   tbl TEXT;   pol RECORD; BEGIN   FOREACH tbl IN ARRAY ARRAY['notifications', 'friendships', 'polls', 'poll_votes']   LOOP     FOR pol IN       SELECT policyname FROM pg_policies WHERE schemaname = 'public' AND tablename = tbl     LOOP       EXECUTE format('DROP POLICY IF EXISTS %I ON public.%I', pol.policyname, tbl);     END LOOP;   END LOOP; END $$; ALTER TABLE public.notifications ENABLE ROW LEVEL SECURITY; ALTER TABLE public.friendships ENABLE ROW LEVEL SECURITY; ALTER TABLE public.polls ENABLE ROW LEVEL SECURITY; ALTER TABLE public.poll_votes ENABLE ROW LEVEL SECURITY; CREATE POLICY "users see own notifications" ON public.notifications   FOR SELECT USING (user_id = auth.uid()); CREATE POLICY "users mark own read" ON public.notifications   FOR UPDATE USING (user_id = auth.uid())   WITH CHECK (user_id = auth.uid()); CREATE POLICY "users delete own notifications" ON public.notifications   FOR DELETE USING (user_id = auth.uid()); CREATE POLICY "notify event members or friend-request recipients" ON public.notifications   FOR INSERT WITH CHECK (     (       data ? 'event_id'       AND (data->>'event_id') ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'       AND (         EXISTS (SELECT 1 FROM public.events e WHERE e.id = (data->>'event_id')::uuid AND e.host_id = auth.uid())         OR EXISTS (SELECT 1 FROM public.event_guests g WHERE g.event_id = (data->>'event_id')::uuid AND g.user_id = auth.uid())       )     )     OR (       type = 'friend_request'       AND data ? 'requester_id'       AND (data->>'requester_id') ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'       AND (data->>'requester_id')::uuid = auth.uid()     )   ); CREATE POLICY "view own friendships" ON public.friendships   FOR SELECT USING (requester_id = auth.uid() OR recipient_id = auth.uid()); CREATE POLICY "send friend requests" ON public.friendships   FOR INSERT WITH CHECK (requester_id = auth.uid()); CREATE POLICY "update own friendships" ON public.friendships   FOR UPDATE USING (requester_id = auth.uid() OR recipient_id = auth.uid())   WITH CHECK (requester_id = auth.uid() OR recipient_id = auth.uid()); CREATE POLICY "delete own friendships" ON public.friendships   FOR DELETE USING (requester_id = auth.uid() OR recipient_id = auth.uid()); CREATE POLICY "polls viewable by everyone" ON public.polls   FOR SELECT USING (true); CREATE POLICY "hosts manage their event polls" ON public.polls   FOR ALL   USING (EXISTS (SELECT 1 FROM public.events e WHERE e.id = polls.event_id AND e.host_id = auth.uid()))   WITH CHECK (EXISTS (SELECT 1 FROM public.events e WHERE e.id = polls.event_id AND e.host_id = auth.uid())); CREATE POLICY "poll votes viewable by everyone" ON public.poll_votes   FOR SELECT USING (true); CREATE POLICY "users cast their own poll votes" ON public.poll_votes   FOR INSERT WITH CHECK (user_id = auth.uid()); CREATE POLICY "users change their own poll votes" ON public.poll_votes   FOR UPDATE USING (user_id = auth.uid())   WITH CHECK (user_id = auth.uid()); CREATE POLICY "users or event hosts delete poll votes" ON public.poll_votes   FOR DELETE USING (     user_id = auth.uid()     OR EXISTS (       SELECT 1 FROM public.polls p       JOIN public.events e ON e.id = p.event_id       WHERE p.id = poll_votes.poll_id AND e.host_id = auth.uid()     )   );